-- ============================================================================
-- Delivery / parcel-logistics database  (MySQL 5.7+ / MariaDB 10.3+ compatible)
-- Generated from 15 CSV files. 163,218 data records across 15 tables.
-- CORRECTION: customers.total_* and riders.total_* (all 0 in source CSV) are recomputed
-- from parcels/deliveries. total_orders=parcels sent; total_cancellations=parcels with
-- current_status='canceled'; total_failed_deliveries / rider total_failures = deliveries
-- whose final_status is not 'delivered'; rider total_deliveries = deliveries assigned.
-- Booleans: True -> 1, False -> 0.  Empty CSV cells -> NULL.
-- delivery_attempts.failure_reason_id: source values like '10.0' stored as 10.
-- ============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET UNIQUE_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';

DROP TABLE IF EXISTS `status_logs`;
DROP TABLE IF EXISTS `returns`;
DROP TABLE IF EXISTS `pre_dispatch_checks`;
DROP TABLE IF EXISTS `payments`;
DROP TABLE IF EXISTS `parcel_items`;
DROP TABLE IF EXISTS `delivery_attempts`;
DROP TABLE IF EXISTS `deliveries`;
DROP TABLE IF EXISTS `parcels`;
DROP TABLE IF EXISTS `routes`;
DROP TABLE IF EXISTS `riders`;
DROP TABLE IF EXISTS `addresses`;
DROP TABLE IF EXISTS `hubs`;
DROP TABLE IF EXISTS `customers`;
DROP TABLE IF EXISTS `failure_reasons`;
DROP TABLE IF EXISTS `cities`;

CREATE TABLE `cities` (
  `city_id` INT NOT NULL,
  `city_name` VARCHAR(50) NOT NULL,
  `province` VARCHAR(50) NOT NULL,
  `postal_code` VARCHAR(5) NOT NULL,
  `latitude` DECIMAL(8,4) NOT NULL,
  `longitude` DECIMAL(8,4) NOT NULL,
  PRIMARY KEY (`city_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `failure_reasons` (
  `reason_id` INT NOT NULL,
  `reason_code` VARCHAR(50) NOT NULL,
  `description` VARCHAR(255) NOT NULL,
  PRIMARY KEY (`reason_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `customers` (
  `customer_id` VARCHAR(10) NOT NULL,
  `full_name` VARCHAR(100) NOT NULL,
  `phone` VARCHAR(11) NOT NULL,
  `email` VARCHAR(100) NOT NULL,
  `registration_date` DATE NOT NULL,
  `city_id` INT NOT NULL,
  `total_orders` INT NOT NULL,
  `total_cancellations` INT NOT NULL,
  `total_failed_deliveries` INT NOT NULL,
  PRIMARY KEY (`customer_id`),
  KEY `idx_customers_city_id` (`city_id`),
  CONSTRAINT `fk_customers_city_id` FOREIGN KEY (`city_id`) REFERENCES `cities` (`city_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `hubs` (
  `hub_id` VARCHAR(6) NOT NULL,
  `hub_name` VARCHAR(100) NOT NULL,
  `city_id` INT NOT NULL,
  `city` VARCHAR(50) NOT NULL,
  `province` VARCHAR(50) NOT NULL,
  `hub_type` VARCHAR(20) NOT NULL,
  `latitude` DECIMAL(8,4) NOT NULL,
  `longitude` DECIMAL(8,4) NOT NULL,
  `is_active` TINYINT(1) NOT NULL,
  PRIMARY KEY (`hub_id`),
  KEY `idx_hubs_city_id` (`city_id`),
  CONSTRAINT `fk_hubs_city_id` FOREIGN KEY (`city_id`) REFERENCES `cities` (`city_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `addresses` (
  `address_id` INT NOT NULL,
  `customer_id` VARCHAR(10) NOT NULL,
  `address_line` VARCHAR(50) NOT NULL,
  `area` VARCHAR(50) NOT NULL,
  `city_id` INT NOT NULL,
  `postal_code` VARCHAR(5) NOT NULL,
  `landmark` VARCHAR(50) NULL,
  `phone_available` TINYINT(1) NOT NULL,
  `address_complete` TINYINT(1) NOT NULL,
  `is_verified` TINYINT(1) NOT NULL,
  PRIMARY KEY (`address_id`),
  KEY `idx_addresses_customer_id` (`customer_id`),
  KEY `idx_addresses_city_id` (`city_id`),
  CONSTRAINT `fk_addresses_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`customer_id`),
  CONSTRAINT `fk_addresses_city_id` FOREIGN KEY (`city_id`) REFERENCES `cities` (`city_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `riders` (
  `rider_id` VARCHAR(9) NOT NULL,
  `full_name` VARCHAR(100) NOT NULL,
  `phone` VARCHAR(11) NOT NULL,
  `vehicle_type` VARCHAR(20) NOT NULL,
  `assigned_hub_id` VARCHAR(6) NOT NULL,
  `is_available` TINYINT(1) NOT NULL,
  `rating` DECIMAL(3,1) NOT NULL,
  `total_deliveries` INT NOT NULL,
  `total_failures` INT NOT NULL,
  PRIMARY KEY (`rider_id`),
  KEY `idx_riders_assigned_hub_id` (`assigned_hub_id`),
  CONSTRAINT `fk_riders_assigned_hub_id` FOREIGN KEY (`assigned_hub_id`) REFERENCES `hubs` (`hub_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `routes` (
  `route_id` INT NOT NULL,
  `origin_hub_id` VARCHAR(6) NOT NULL,
  `destination_hub_id` VARCHAR(6) NOT NULL,
  `distance_km` DECIMAL(8,2) NOT NULL,
  `estimated_hours` DECIMAL(6,2) NOT NULL,
  `is_active` TINYINT(1) NOT NULL,
  PRIMARY KEY (`route_id`),
  KEY `idx_routes_origin_hub_id` (`origin_hub_id`),
  KEY `idx_routes_destination_hub_id` (`destination_hub_id`),
  CONSTRAINT `fk_routes_origin_hub_id` FOREIGN KEY (`origin_hub_id`) REFERENCES `hubs` (`hub_id`),
  CONSTRAINT `fk_routes_destination_hub_id` FOREIGN KEY (`destination_hub_id`) REFERENCES `hubs` (`hub_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `parcels` (
  `parcel_id` INT NOT NULL,
  `tracking_number` VARCHAR(9) NOT NULL,
  `sender_id` VARCHAR(10) NOT NULL,
  `sender_address_id` INT NOT NULL,
  `receiver_name` VARCHAR(100) NOT NULL,
  `receiver_phone` VARCHAR(11) NULL,
  `receiver_address_id` INT NOT NULL,
  `origin_hub_id` VARCHAR(6) NOT NULL,
  `destination_hub_id` VARCHAR(6) NOT NULL,
  `booking_date` DATETIME NOT NULL,
  `category` VARCHAR(50) NOT NULL,
  `declared_value` DECIMAL(12,2) NOT NULL,
  `weight_kg` DECIMAL(8,3) NOT NULL,
  `length_cm` DECIMAL(6,1) NOT NULL,
  `width_cm` DECIMAL(6,1) NOT NULL,
  `height_cm` DECIMAL(6,1) NOT NULL,
  `current_status` VARCHAR(20) NOT NULL,
  `is_cod` TINYINT(1) NOT NULL,
  PRIMARY KEY (`parcel_id`),
  KEY `idx_parcels_sender_id` (`sender_id`),
  KEY `idx_parcels_sender_address_id` (`sender_address_id`),
  KEY `idx_parcels_receiver_address_id` (`receiver_address_id`),
  KEY `idx_parcels_origin_hub_id` (`origin_hub_id`),
  KEY `idx_parcels_destination_hub_id` (`destination_hub_id`),
  CONSTRAINT `fk_parcels_sender_id` FOREIGN KEY (`sender_id`) REFERENCES `customers` (`customer_id`),
  CONSTRAINT `fk_parcels_sender_address_id` FOREIGN KEY (`sender_address_id`) REFERENCES `addresses` (`address_id`),
  CONSTRAINT `fk_parcels_receiver_address_id` FOREIGN KEY (`receiver_address_id`) REFERENCES `addresses` (`address_id`),
  CONSTRAINT `fk_parcels_origin_hub_id` FOREIGN KEY (`origin_hub_id`) REFERENCES `hubs` (`hub_id`),
  CONSTRAINT `fk_parcels_destination_hub_id` FOREIGN KEY (`destination_hub_id`) REFERENCES `hubs` (`hub_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `deliveries` (
  `delivery_id` INT NOT NULL,
  `parcel_id` INT NOT NULL,
  `rider_id` VARCHAR(9) NOT NULL,
  `route_id` INT NOT NULL,
  `assignment_time` DATETIME NOT NULL,
  `pickup_time` DATETIME NOT NULL,
  `out_for_delivery_time` DATETIME NOT NULL,
  `delivery_time` DATETIME NULL,
  `final_status` VARCHAR(20) NOT NULL,
  `total_attempts` INT NOT NULL,
  PRIMARY KEY (`delivery_id`),
  KEY `idx_deliveries_parcel_id` (`parcel_id`),
  KEY `idx_deliveries_rider_id` (`rider_id`),
  KEY `idx_deliveries_route_id` (`route_id`),
  CONSTRAINT `fk_deliveries_parcel_id` FOREIGN KEY (`parcel_id`) REFERENCES `parcels` (`parcel_id`),
  CONSTRAINT `fk_deliveries_rider_id` FOREIGN KEY (`rider_id`) REFERENCES `riders` (`rider_id`),
  CONSTRAINT `fk_deliveries_route_id` FOREIGN KEY (`route_id`) REFERENCES `routes` (`route_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `delivery_attempts` (
  `attempt_id` INT NOT NULL,
  `delivery_id` INT NOT NULL,
  `attempt_number` INT NOT NULL,
  `attempt_datetime` DATETIME NOT NULL,
  `was_successful` TINYINT(1) NOT NULL,
  `failure_reason_id` INT NULL,
  `rider_notes` VARCHAR(255) NULL,
  `reattempt_scheduled` TINYINT(1) NOT NULL,
  PRIMARY KEY (`attempt_id`),
  KEY `idx_delivery_attempts_delivery_id` (`delivery_id`),
  KEY `idx_delivery_attempts_failure_reason_id` (`failure_reason_id`),
  CONSTRAINT `fk_delivery_attempts_delivery_id` FOREIGN KEY (`delivery_id`) REFERENCES `deliveries` (`delivery_id`),
  CONSTRAINT `fk_delivery_attempts_failure_reason_id` FOREIGN KEY (`failure_reason_id`) REFERENCES `failure_reasons` (`reason_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `parcel_items` (
  `item_id` INT NOT NULL,
  `parcel_id` INT NOT NULL,
  `item_name` VARCHAR(100) NOT NULL,
  `quantity` INT NOT NULL,
  `unit_price` DECIMAL(10,2) NOT NULL,
  `item_category` VARCHAR(50) NOT NULL,
  PRIMARY KEY (`item_id`),
  KEY `idx_parcel_items_parcel_id` (`parcel_id`),
  CONSTRAINT `fk_parcel_items_parcel_id` FOREIGN KEY (`parcel_id`) REFERENCES `parcels` (`parcel_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `payments` (
  `payment_id` INT NOT NULL,
  `parcel_id` INT NOT NULL,
  `payment_method` VARCHAR(30) NOT NULL,
  `order_value` DECIMAL(12,2) NOT NULL,
  `discount_amount` DECIMAL(12,2) NOT NULL,
  `net_amount` DECIMAL(12,2) NOT NULL,
  `cod_amount` DECIMAL(12,2) NULL,
  `cod_collected` TINYINT(1) NOT NULL,
  `cod_collection_date` DATETIME NULL,
  `collected_by_rider_id` VARCHAR(9) NULL,
  `settlement_date` DATE NULL,
  `refund_issued` TINYINT(1) NOT NULL,
  `refund_date` DATE NULL,
  `payment_status` VARCHAR(20) NOT NULL,
  PRIMARY KEY (`payment_id`),
  KEY `idx_payments_parcel_id` (`parcel_id`),
  KEY `idx_payments_collected_by_rider_id` (`collected_by_rider_id`),
  CONSTRAINT `fk_payments_parcel_id` FOREIGN KEY (`parcel_id`) REFERENCES `parcels` (`parcel_id`),
  CONSTRAINT `fk_payments_collected_by_rider_id` FOREIGN KEY (`collected_by_rider_id`) REFERENCES `riders` (`rider_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `pre_dispatch_checks` (
  `check_id` INT NOT NULL,
  `parcel_id` INT NOT NULL,
  `checked_at` DATETIME NOT NULL,
  `phone_present` TINYINT(1) NOT NULL,
  `address_complete` TINYINT(1) NOT NULL,
  `city_valid` TINYINT(1) NOT NULL,
  `postal_code_valid` TINYINT(1) NOT NULL,
  `landmark_available` TINYINT(1) NOT NULL,
  `prev_cancellations` INT NOT NULL,
  `prev_failed_deliveries` INT NOT NULL,
  `prev_successful_deliveries` INT NOT NULL,
  `is_cod` TINYINT(1) NOT NULL,
  `order_value` DECIMAL(12,2) NOT NULL,
  `weight_kg` DECIMAL(8,3) NOT NULL,
  `destination_area_failure_rate` DECIMAL(6,4) NOT NULL,
  `risk_score` INT NOT NULL,
  `dispatch_decision` VARCHAR(20) NOT NULL,
  `flag_no_phone` TINYINT(1) NOT NULL,
  `flag_incomplete_address` TINYINT(1) NOT NULL,
  `flag_invalid_city` TINYINT(1) NOT NULL,
  `flag_invalid_postal` TINYINT(1) NOT NULL,
  `flag_no_landmark` TINYINT(1) NOT NULL,
  `flag_high_cancellations` TINYINT(1) NOT NULL,
  `flag_high_failures` TINYINT(1) NOT NULL,
  `flag_high_cod` TINYINT(1) NOT NULL,
  `flag_high_area_risk` TINYINT(1) NOT NULL,
  PRIMARY KEY (`check_id`),
  KEY `idx_pre_dispatch_checks_parcel_id` (`parcel_id`),
  CONSTRAINT `fk_pre_dispatch_checks_parcel_id` FOREIGN KEY (`parcel_id`) REFERENCES `parcels` (`parcel_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `returns` (
  `return_id` VARCHAR(9) NOT NULL,
  `parcel_id` INT NOT NULL,
  `return_reason` VARCHAR(100) NOT NULL,
  `return_to_origin` TINYINT(1) NOT NULL,
  `return_date` DATE NOT NULL,
  `refund_issued` TINYINT(1) NOT NULL,
  `refund_date` DATE NULL,
  `return_status` VARCHAR(20) NOT NULL,
  PRIMARY KEY (`return_id`),
  KEY `idx_returns_parcel_id` (`parcel_id`),
  CONSTRAINT `fk_returns_parcel_id` FOREIGN KEY (`parcel_id`) REFERENCES `parcels` (`parcel_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `status_logs` (
  `log_id` INT NOT NULL,
  `parcel_id` INT NOT NULL,
  `status` VARCHAR(30) NOT NULL,
  `hub_id` VARCHAR(6) NOT NULL,
  `rider_id` VARCHAR(9) NULL,
  `logged_at` DATETIME NOT NULL,
  `location_note` VARCHAR(255) NULL,
  `entered_by` VARCHAR(30) NOT NULL,
  PRIMARY KEY (`log_id`),
  KEY `idx_status_logs_parcel_id` (`parcel_id`),
  KEY `idx_status_logs_hub_id` (`hub_id`),
  KEY `idx_status_logs_rider_id` (`rider_id`),
  CONSTRAINT `fk_status_logs_parcel_id` FOREIGN KEY (`parcel_id`) REFERENCES `parcels` (`parcel_id`),
  CONSTRAINT `fk_status_logs_hub_id` FOREIGN KEY (`hub_id`) REFERENCES `hubs` (`hub_id`),
  CONSTRAINT `fk_status_logs_rider_id` FOREIGN KEY (`rider_id`) REFERENCES `riders` (`rider_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

START TRANSACTION;

-- ---- cities: 30 rows ----

-- ---- failure_reasons: 10 rows ----

